-- Mizan database setup (generated by scripts/build-setup-sql.mjs; do not edit by hand).
-- Paste this whole file into Supabase → SQL Editor → New query → Run.
-- Safe to run more than once: every statement is idempotent.

-- ────────────────────────────────────────────────────────────────────────────
-- 20261011000001_core.sql
-- ────────────────────────────────────────────────────────────────────────────

-- ============================================================================
--  Mizan · 0001 · Core schema
--  Every table: id, user_id, created_at, updated_at (client edit time, decides
--  last-write-wins), deleted_at (soft delete / tombstone) and server_updated_at
--  (server clock, used only as the incremental pull cursor).
-- ============================================================================

-- ── Row metadata + last-write-wins ──────────────────────────────────────────
create or replace function public.mizan_row_meta()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if new.updated_at is null or new.updated_at > now() + interval '2 minutes' then
      new.updated_at := now();
    end if;
    if new.created_at is null or new.created_at > now() + interval '2 minutes' then
      new.created_at := now();
    end if;
  else
    -- Identity and ownership never change.
    new.id := old.id;
    new.user_id := old.user_id;
    new.created_at := old.created_at;
    -- A write older than the stored row loses. Returning NULL skips the update,
    -- which also makes INSERT … ON CONFLICT DO UPDATE (upsert) a silent no-op.
    if new.updated_at < old.updated_at then
      return null;
    end if;
    -- A device clock far in the future is clamped so it cannot win forever.
    if new.updated_at > now() + interval '2 minutes' then
      new.updated_at := now();
    end if;
  end if;
  new.server_updated_at := clock_timestamp();
  return new;
end;
$$;

-- ── profiles & settings (one row per user, id = user_id) ────────────────────
create table if not exists public.profiles (
  id                uuid primary key references auth.users (id) on delete cascade,
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  display_name      text not null default '' check (char_length(display_name) <= 80),
  onboarded_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  constraint profiles_id_is_user check (id = user_id)
);

create table if not exists public.settings (
  id                       uuid primary key references auth.users (id) on delete cascade,
  user_id                  uuid not null default auth.uid() references auth.users (id) on delete cascade,
  language                 text not null default 'ar' check (language in ('ar', 'en')),
  theme                    text not null default 'dark' check (theme in ('dark', 'light', 'system')),
  week_start               smallint not null default 0 check (week_start in (0, 1, 6)),
  calendar_primary         text not null default 'gregorian' check (calendar_primary in ('gregorian', 'hijri')),
  calendar_show_secondary  boolean not null default true,
  notifications            jsonb not null default '{"push": false, "in_app": true, "offsets_min": [1440, 60]}',
  timer_defaults           jsonb not null default '{}',
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  deleted_at               timestamptz,
  server_updated_at        timestamptz not null default now(),
  constraint settings_id_is_user check (id = user_id),
  constraint settings_json_size check (pg_column_size(notifications) < 4096 and pg_column_size(timer_defaults) < 16384)
);

-- ── subjects ────────────────────────────────────────────────────────────────
create table if not exists public.subjects (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name              text not null check (char_length(name) between 1 and 60),
  color             text not null check (color ~ '^#[0-9A-Fa-f]{6}$'),
  icon              text not null default 'book-open' check (char_length(icon) <= 40),
  position          text not null collate "C",
  archived_at       timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  unique (id, user_id)
);

-- ── boards & columns ────────────────────────────────────────────────────────
create table if not exists public.boards (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name              text not null check (char_length(name) between 1 and 80),
  position          text not null collate "C",
  archived_at       timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  unique (id, user_id)
);

create table if not exists public.columns (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  board_id          uuid not null,
  name              text not null check (char_length(name) between 1 and 60),
  color             text check (color is null or color ~ '^#[0-9A-Fa-f]{6}$'),
  kind              text check (kind is null or kind in ('todo', 'doing', 'done')),
  position          text not null collate "C",
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  unique (id, user_id),
  -- Composite keys make it impossible to attach a row to another user's parent.
  foreign key (board_id, user_id) references public.boards (id, user_id) on delete cascade
);

-- ── cards ───────────────────────────────────────────────────────────────────
create table if not exists public.cards (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  board_id          uuid not null,
  column_id         uuid not null,
  subject_id        uuid,
  title             text not null check (char_length(title) between 1 and 300),
  description       text not null default '' check (char_length(description) <= 20000),
  notes             text not null default '' check (char_length(notes) <= 20000),
  due_at            timestamptz,
  due_has_time      boolean not null default false,
  priority          text not null default 'med' check (priority in ('low', 'med', 'high')),
  labels            text[] not null default '{}' check (cardinality(labels) <= 20),
  is_exam           boolean not null default false,
  estimate_min      integer check (estimate_min is null or estimate_min between 1 and 1440),
  repeat_rule       jsonb check (repeat_rule is null or pg_column_size(repeat_rule) < 2048),
  position          text not null collate "C",
  completed_at      timestamptz,
  is_sample         boolean not null default false,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (board_id, user_id)   references public.boards (id, user_id) on delete cascade,
  foreign key (column_id, user_id)  references public.columns (id, user_id) on delete cascade,
  foreign key (subject_id, user_id) references public.subjects (id, user_id) on delete set null (subject_id)
);

create table if not exists public.checklist_items (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  card_id           uuid not null,
  text              text not null check (char_length(text) between 1 and 500),
  done              boolean not null default false,
  position          text not null collate "C",
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  foreign key (card_id, user_id) references public.cards (id, user_id) on delete cascade
);

create table if not exists public.attachments (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  card_id           uuid not null,
  storage_path      text not null check (char_length(storage_path) <= 512),
  name              text not null check (char_length(name) between 1 and 255),
  mime              text not null check (char_length(mime) <= 120),
  size_bytes        integer not null check (size_bytes between 0 and 20971520),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  foreign key (card_id, user_id) references public.cards (id, user_id) on delete cascade,
  -- Files live under <user_id>/… so storage policies can scope them.
  constraint attachments_path_scoped check (split_part(storage_path, '/', 1) = user_id::text)
);

-- ── focus timer ─────────────────────────────────────────────────────────────
create table if not exists public.focus_sessions (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  subject_id        uuid,
  card_id           uuid,
  kind              text not null check (kind in ('focus', 'short_break', 'long_break', 'open')),
  started_at        timestamptz not null,
  ended_at          timestamptz not null,
  planned_sec       integer check (planned_sec is null or planned_sec between 1 and 86400),
  focused_sec       integer not null check (focused_sec between 0 and 86400),
  completed         boolean not null default false,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  check (ended_at >= started_at),
  foreign key (subject_id, user_id) references public.subjects (id, user_id) on delete set null (subject_id),
  foreign key (card_id, user_id)    references public.cards (id, user_id) on delete set null (card_id)
);

-- One row per user: the running timer, so it can be resumed on another device.
create table if not exists public.timer_state (
  id                uuid primary key references auth.users (id) on delete cascade,
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  state             jsonb not null default '{}' check (pg_column_size(state) < 8192),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  constraint timer_state_id_is_user check (id = user_id)
);

-- ── tutor ───────────────────────────────────────────────────────────────────
create table if not exists public.chat_threads (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  subject_id        uuid,
  title             text not null default '' check (char_length(title) <= 200),
  last_message_at   timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (subject_id, user_id) references public.subjects (id, user_id) on delete set null (subject_id)
);

create table if not exists public.chat_messages (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  thread_id         uuid not null,
  role              text not null check (role in ('user', 'assistant')),
  content           jsonb not null check (pg_column_size(content) < 262144),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  foreign key (thread_id, user_id) references public.chat_threads (id, user_id) on delete cascade
);

create table if not exists public.flashcards (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  subject_id        uuid,
  front             text not null check (char_length(front) between 1 and 2000),
  back              text not null check (char_length(back) between 1 and 4000),
  ease              real not null default 2.5 check (ease between 1.3 and 5),
  interval_days     real not null default 0 check (interval_days >= 0),
  repetitions       integer not null default 0 check (repetitions >= 0),
  lapses            integer not null default 0 check (lapses >= 0),
  due_at            timestamptz not null default now(),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  foreign key (subject_id, user_id) references public.subjects (id, user_id) on delete set null (subject_id)
);

-- ── Triggers + indexes for every table ──────────────────────────────────────
do $$
declare
  t text;
begin
  foreach t in array array[
    'profiles', 'settings', 'subjects', 'boards', 'columns', 'cards', 'checklist_items',
    'attachments', 'focus_sessions', 'timer_state', 'chat_threads', 'chat_messages', 'flashcards'
  ] loop
    execute format('drop trigger if exists mizan_row_meta on public.%I', t);
    execute format(
      'create trigger mizan_row_meta before insert or update on public.%I
         for each row execute function public.mizan_row_meta()', t);
    execute format(
      'create index if not exists %I on public.%I (user_id, server_updated_at)', t || '_pull_idx', t);
  end loop;
end;
$$;

create index if not exists columns_board_idx         on public.columns (board_id);
create index if not exists cards_board_idx           on public.cards (board_id);
create index if not exists cards_column_idx          on public.cards (column_id);
create index if not exists cards_subject_idx         on public.cards (subject_id);
create index if not exists cards_due_idx             on public.cards (user_id, due_at) where deleted_at is null;
create index if not exists checklist_card_idx        on public.checklist_items (card_id);
create index if not exists attachments_card_idx      on public.attachments (card_id);
create index if not exists focus_sessions_time_idx   on public.focus_sessions (user_id, started_at);
create index if not exists focus_sessions_card_idx   on public.focus_sessions (card_id);
create index if not exists focus_sessions_subj_idx   on public.focus_sessions (subject_id);
create index if not exists chat_threads_subject_idx  on public.chat_threads (subject_id);
create index if not exists chat_messages_thread_idx  on public.chat_messages (thread_id, created_at);
create index if not exists flashcards_due_idx        on public.flashcards (user_id, due_at) where deleted_at is null;
create index if not exists flashcards_subject_idx    on public.flashcards (subject_id);

-- ── New users get a profile and settings row ────────────────────────────────
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, user_id, display_name)
  values (new.id, new.id, coalesce(left(new.raw_user_meta_data ->> 'full_name', 80), ''))
  on conflict (id) do nothing;

  insert into public.settings (id, user_id)
  values (new.id, new.id)
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ────────────────────────────────────────────────────────────────────────────
-- 20261011000002_rls.sql
-- ────────────────────────────────────────────────────────────────────────────

-- ============================================================================
--  Mizan · 0002 · Row Level Security on EVERY table
--  A signed-in user can read and write only rows where user_id = their id.
--  Anonymous requests get nothing.
-- ============================================================================

do $$
declare
  t text;
begin
  foreach t in array array[
    'profiles', 'settings', 'subjects', 'boards', 'columns', 'cards', 'checklist_items',
    'attachments', 'focus_sessions', 'timer_state', 'chat_threads', 'chat_messages', 'flashcards'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);

    execute format('drop policy if exists "own rows: select" on public.%I', t);
    execute format('drop policy if exists "own rows: insert" on public.%I', t);
    execute format('drop policy if exists "own rows: update" on public.%I', t);
    execute format('drop policy if exists "own rows: delete" on public.%I', t);

    -- (select auth.uid()) is evaluated once per statement, not per row.
    execute format(
      'create policy "own rows: select" on public.%I for select to authenticated
         using (user_id = (select auth.uid()))', t);
    execute format(
      'create policy "own rows: insert" on public.%I for insert to authenticated
         with check (user_id = (select auth.uid()))', t);
    execute format(
      'create policy "own rows: update" on public.%I for update to authenticated
         using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))', t);
    execute format(
      'create policy "own rows: delete" on public.%I for delete to authenticated
         using (user_id = (select auth.uid()))', t);
  end loop;
end;
$$;

-- Trigger functions are not meant to be called over the API.
revoke execute on function public.mizan_row_meta() from public, anon, authenticated;
revoke execute on function public.handle_new_user() from public, anon, authenticated;

-- ────────────────────────────────────────────────────────────────────────────
-- 20261011000003_storage.sql
-- ────────────────────────────────────────────────────────────────────────────

-- ============================================================================
--  Mizan · 0003 · Private storage bucket for card attachments
--  Path layout: <user_id>/<card_id>/<file_id>-<name>
--  Limits: 20 MB per file; PDFs, images, Office documents and plain text only.
-- ============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'attachments',
  'attachments',
  false,
  20971520,
  array[
    'application/pdf',
    'image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/heic', 'image/heif',
    'text/plain', 'text/markdown',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-powerpoint',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  ]
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "attachments: read own"   on storage.objects;
drop policy if exists "attachments: upload own" on storage.objects;
drop policy if exists "attachments: update own" on storage.objects;
drop policy if exists "attachments: delete own" on storage.objects;

create policy "attachments: read own" on storage.objects for select to authenticated
  using (bucket_id = 'attachments' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "attachments: upload own" on storage.objects for insert to authenticated
  with check (bucket_id = 'attachments' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "attachments: update own" on storage.objects for update to authenticated
  using (bucket_id = 'attachments' and (storage.foldername(name))[1] = (select auth.uid())::text)
  with check (bucket_id = 'attachments' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "attachments: delete own" on storage.objects for delete to authenticated
  using (bucket_id = 'attachments' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- ────────────────────────────────────────────────────────────────────────────
-- 20261011000004_realtime.sql
-- ────────────────────────────────────────────────────────────────────────────

-- ============================================================================
--  Mizan · 0004 · Realtime: broadcast row changes so other devices update live.
--  Realtime respects RLS, so each user only receives their own rows.
-- ============================================================================

do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
  foreach t in array array[
    'profiles', 'settings', 'subjects', 'boards', 'columns', 'cards', 'checklist_items',
    'attachments', 'focus_sessions', 'timer_state', 'chat_threads', 'chat_messages', 'flashcards'
  ] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end;
$$;

-- ────────────────────────────────────────────────────────────────────────────
-- 20261011000005_reminders.sql
-- ────────────────────────────────────────────────────────────────────────────

-- ============================================================================
--  Mizan · 0005 · Reminders and web push
--  - cards.reminder_offsets: per-card override (NULL = user defaults, {} = off)
--  - settings.timezone: needed to place date-only reminders at 08:00 local
--  - push_subscriptions: one row per browser/device that accepted push
--  - reminder_log: what has been sent, so nothing is sent twice
--  - due_reminders(): the reminders due in a window (service role only)
-- ============================================================================

alter table public.cards
  add column if not exists reminder_offsets integer[]
  check (
    reminder_offsets is null
    or (cardinality(reminder_offsets) <= 8 and 0 <= all (reminder_offsets) and 40320 >= all (reminder_offsets))
  );

alter table public.settings
  add column if not exists timezone text not null default 'Asia/Bahrain'
  check (char_length(timezone) between 1 and 64);

-- ── Push subscriptions (written directly by the client, never synced to IndexedDB) ──
create table if not exists public.push_subscriptions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  endpoint    text not null unique check (endpoint ~ '^https://' and char_length(endpoint) <= 1024),
  p256dh      text not null check (char_length(p256dh) <= 256),
  auth        text not null check (char_length(auth) <= 64),
  user_agent  text not null default '' check (char_length(user_agent) <= 300),
  created_at  timestamptz not null default now(),
  last_used_at timestamptz
);
create index if not exists push_subscriptions_user_idx on public.push_subscriptions (user_id);

alter table public.push_subscriptions enable row level security;
revoke all on public.push_subscriptions from anon;
grant select, insert, update, delete on public.push_subscriptions to authenticated;
drop policy if exists "own subscriptions" on public.push_subscriptions;
create policy "own subscriptions" on public.push_subscriptions for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- ── Sent log (server only: RLS on, no policies) ─────────────────────────────
create table if not exists public.reminder_log (
  card_id    uuid not null references public.cards (id) on delete cascade,
  offset_min integer not null,
  due_at     timestamptz not null,
  user_id    uuid not null references auth.users (id) on delete cascade,
  sent_at    timestamptz not null default now(),
  primary key (card_id, offset_min, due_at)
);
alter table public.reminder_log enable row level security;
revoke all on public.reminder_log from anon, authenticated;

create index if not exists cards_open_due_idx on public.cards (due_at)
  where deleted_at is null and completed_at is null and due_at is not null;

-- ── Which reminders fall in (p_from, p_to]? Mirrors src/features/reminders/compute.ts ──
create or replace function public.due_reminders(p_from timestamptz, p_to timestamptz)
returns table (
  user_id      uuid,
  card_id      uuid,
  board_id     uuid,
  title        text,
  is_exam      boolean,
  due_at       timestamptz,
  due_has_time boolean,
  offset_min   integer,
  fire_at      timestamptz,
  subject_name text,
  language     text,
  timezone     text
)
language sql
stable
security definer
set search_path = ''
as $$
  with prefs as (
    select s.user_id, s.language, s.timezone, s.notifications
    from public.settings s
    where coalesce((s.notifications ->> 'push')::boolean, false)
  ),
  candidates as (
    select c.*, p.language, p.timezone, p.notifications
    from public.cards c
    join prefs p on p.user_id = c.user_id
    join public.boards b on b.id = c.board_id and b.deleted_at is null and b.archived_at is null
    where c.deleted_at is null
      and c.completed_at is null
      and c.due_at is not null
      -- Reminders are at most 4 weeks before the due date.
      and c.due_at > p_from
      and c.due_at <= p_to + interval '29 days'
  ),
  expanded as (
    select distinct
      c.id as card_id,
      case
        when c.due_has_time then x
        when x < 1440 then 0
        else (round(x / 1440.0) * 1440)::integer
      end as offset_min
    from candidates c
    cross join lateral unnest(
      coalesce(
        c.reminder_offsets,
        array(select jsonb_array_elements_text(coalesce(c.notifications -> 'offsets_min', '[1440, 60]'::jsonb))::integer)
      )
    ) as x
    where x between 0 and 40320
  )
  select
    c.user_id, c.id, c.board_id, c.title, c.is_exam, c.due_at, c.due_has_time, e.offset_min, f.fire_at,
    sub.name, c.language, c.timezone
  from expanded e
  join candidates c on c.id = e.card_id
  cross join lateral (
    select case
      when c.due_has_time then c.due_at - make_interval(mins => e.offset_min)
      else (
        date_trunc('day', c.due_at at time zone c.timezone)
        - make_interval(days => e.offset_min / 1440)
        + interval '8 hours'
      ) at time zone c.timezone
    end as fire_at
  ) f
  left join public.subjects sub on sub.id = c.subject_id and sub.deleted_at is null
  where f.fire_at > p_from
    and f.fire_at <= p_to
    and not exists (
      select 1 from public.reminder_log l
      where l.card_id = c.id and l.offset_min = e.offset_min and l.due_at = c.due_at
    )
  order by f.fire_at;
$$;

revoke execute on function public.due_reminders(timestamptz, timestamptz) from public, anon, authenticated;
grant execute on function public.due_reminders(timestamptz, timestamptz) to service_role;

-- ────────────────────────────────────────────────────────────────────────────
-- 20261011000006_tutor.sql
-- ────────────────────────────────────────────────────────────────────────────

-- ============================================================================
--  Mizan · 0006 · AI tutor
--  - study_topics: per-subject topic accuracy (synced, RLS) for weak-topic tracking
--  - ai_usage: per-user daily usage + a one-minute request window (server only)
--  - tutor_files: Anthropic Files API uploads, so a user can only reference their own
--  - ai_reserve()/ai_record(): atomic rate limiting and usage accounting (service role only)
-- ============================================================================

create table if not exists public.study_topics (
  id                uuid primary key,
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  subject_id        uuid,
  topic             text not null check (char_length(topic) between 1 and 120),
  attempts          integer not null default 0 check (attempts >= 0),
  correct           integer not null default 0 check (correct >= 0 and correct <= attempts),
  last_seen_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  foreign key (subject_id, user_id) references public.subjects (id, user_id) on delete set null (subject_id)
);
create index if not exists study_topics_subject_idx on public.study_topics (subject_id);
drop trigger if exists mizan_row_meta on public.study_topics;
create trigger mizan_row_meta before insert or update on public.study_topics for each row execute function public.mizan_row_meta();
create index if not exists study_topics_pull_idx on public.study_topics (user_id, server_updated_at);

alter table public.study_topics enable row level security;
revoke all on public.study_topics from anon;
grant select, insert, update, delete on public.study_topics to authenticated;
drop policy if exists "own rows: select" on public.study_topics;
drop policy if exists "own rows: insert" on public.study_topics;
drop policy if exists "own rows: update" on public.study_topics;
drop policy if exists "own rows: delete" on public.study_topics;
create policy "own rows: select" on public.study_topics for select to authenticated using (user_id = (select auth.uid()));
create policy "own rows: insert" on public.study_topics for insert to authenticated with check (user_id = (select auth.uid()));
create policy "own rows: update" on public.study_topics for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "own rows: delete" on public.study_topics for delete to authenticated using (user_id = (select auth.uid()));

do $$
begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'study_topics') then
    alter publication supabase_realtime add table public.study_topics;
  end if;
end;
$$;

-- ── Usage (server only: RLS on, no policies) ────────────────────────────────
create table if not exists public.ai_usage (
  user_id      uuid not null references auth.users (id) on delete cascade,
  day          date not null,
  messages     integer not null default 0,
  tokens       bigint  not null default 0,
  minute_start timestamptz,
  minute_count integer not null default 0,
  primary key (user_id, day)
);
alter table public.ai_usage enable row level security;
revoke all on public.ai_usage from anon, authenticated;

create table if not exists public.tutor_files (
  file_id    text primary key check (file_id ~ '^file_[A-Za-z0-9_-]{4,120}$'),
  user_id    uuid not null references auth.users (id) on delete cascade,
  mime       text not null,
  created_at timestamptz not null default now()
);
create index if not exists tutor_files_user_idx on public.tutor_files (user_id);
alter table public.tutor_files enable row level security;
revoke all on public.tutor_files from anon, authenticated;

/**
 * Atomically checks and counts one tutor request.
 * Returns {ok:true, messages_left, tokens_left} or {ok:false, reason, retry_after?}.
 * reason: 'daily_messages' | 'daily_tokens' | 'rate_limited'
 */
create or replace function public.ai_reserve(
  p_user uuid,
  p_is_message boolean,
  p_per_minute integer,
  p_daily_messages integer,
  p_daily_tokens bigint,
  p_tz text default 'Asia/Bahrain'
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  tz text := case when exists (select 1 from pg_catalog.pg_timezone_names where name = p_tz) then p_tz else 'Asia/Bahrain' end;
  d date := (now() at time zone tz)::date;
  r public.ai_usage;
begin
  insert into public.ai_usage (user_id, day) values (p_user, d) on conflict do nothing;
  select * into r from public.ai_usage where user_id = p_user and day = d for update;

  if r.tokens >= p_daily_tokens then
    return jsonb_build_object('ok', false, 'reason', 'daily_tokens');
  end if;
  if p_is_message and r.messages >= p_daily_messages then
    return jsonb_build_object('ok', false, 'reason', 'daily_messages');
  end if;

  if r.minute_start is null or now() - r.minute_start >= interval '1 minute' then
    r.minute_start := now();
    r.minute_count := 0;
  end if;
  if r.minute_count >= p_per_minute then
    return jsonb_build_object('ok', false, 'reason', 'rate_limited',
      'retry_after', greatest(1, ceil(extract(epoch from (r.minute_start + interval '1 minute' - now())))::integer));
  end if;

  update public.ai_usage
     set minute_start = r.minute_start,
         minute_count = r.minute_count + 1,
         messages = messages + case when p_is_message then 1 else 0 end
   where user_id = p_user and day = d
  returning * into r;

  return jsonb_build_object('ok', true,
    'messages_left', greatest(0, p_daily_messages - r.messages),
    'tokens_left', greatest(0, p_daily_tokens - r.tokens));
end;
$$;

create or replace function public.ai_record(p_user uuid, p_tokens bigint, p_tz text default 'Asia/Bahrain')
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.ai_usage (user_id, day, tokens)
  values (
    p_user,
    (now() at time zone (case when exists (select 1 from pg_catalog.pg_timezone_names where name = p_tz) then p_tz else 'Asia/Bahrain' end))::date,
    greatest(0, p_tokens)
  )
  on conflict (user_id, day) do update set tokens = public.ai_usage.tokens + excluded.tokens;
$$;

revoke execute on function public.ai_reserve(uuid, boolean, integer, integer, bigint, text) from public, anon, authenticated;
revoke execute on function public.ai_record(uuid, bigint, text) from public, anon, authenticated;
grant execute on function public.ai_reserve(uuid, boolean, integer, integer, bigint, text) to service_role;
grant execute on function public.ai_record(uuid, bigint, text) to service_role;

-- ────────────────────────────────────────────────────────────────────────────
-- 20261105000007_books.sql
-- ────────────────────────────────────────────────────────────────────────────

-- ============================================================================
--  Mizan · 0007 · Books: a personal reading log (shelf, ratings, notes, quotes).
--  Same conventions as every synced table: LWW trigger, soft delete, RLS, realtime.
-- ============================================================================

create table if not exists public.books (
  id                uuid primary key,
  user_id           uuid not null default auth.uid() references auth.users (id) on delete cascade,
  title             text not null check (char_length(title) between 1 and 300),
  author            text not null default '' check (char_length(author) <= 200),
  /* An https URL (e.g. Open Library) or a small data:image/jpeg URL from the user's own photo. */
  cover_url         text check (cover_url is null or (char_length(cover_url) <= 150000 and (cover_url like 'https://%' or cover_url like 'data:image/jpeg;base64,%'))),
  isbn              text check (isbn is null or isbn ~ '^[0-9Xx-]{10,17}$'),
  status            text not null default 'want' check (status in ('want', 'reading', 'finished', 'dropped')),
  rating            smallint check (rating is null or rating between 1 and 5),
  pages             integer check (pages is null or pages between 1 and 20000),
  current_page      integer not null default 0 check (current_page >= 0),
  started_on        date,
  finished_on       date,
  language          text check (language is null or language in ('ar', 'en', 'other')),
  genre             text not null default '' check (char_length(genre) <= 80),
  tags              text[] not null default '{}' check (cardinality(tags) <= 20),
  notes             text not null default '' check (char_length(notes) <= 50000),
  quotes            jsonb not null default '[]' check (jsonb_typeof(quotes) = 'array' and pg_column_size(quotes) < 131072),
  favorite          boolean not null default false,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  server_updated_at timestamptz not null default now(),
  check (finished_on is null or started_on is null or finished_on >= started_on)
);

create index if not exists books_pull_idx on public.books (user_id, server_updated_at);
create index if not exists books_status_idx on public.books (user_id, status) where deleted_at is null;

drop trigger if exists mizan_row_meta on public.books;
create trigger mizan_row_meta before insert or update on public.books for each row execute function public.mizan_row_meta();

alter table public.books enable row level security;
revoke all on public.books from anon;
grant select, insert, update, delete on public.books to authenticated;
drop policy if exists "own rows: select" on public.books;
drop policy if exists "own rows: insert" on public.books;
drop policy if exists "own rows: update" on public.books;
drop policy if exists "own rows: delete" on public.books;
create policy "own rows: select" on public.books for select to authenticated using (user_id = (select auth.uid()));
create policy "own rows: insert" on public.books for insert to authenticated with check (user_id = (select auth.uid()));
create policy "own rows: update" on public.books for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "own rows: delete" on public.books for delete to authenticated using (user_id = (select auth.uid()));

do $$
begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'books') then
    alter publication supabase_realtime add table public.books;
  end if;
end;
$$;

-- ────────────────────────────────────────────────────────────────────────────
-- 20261106000008_book_covers.sql
-- ────────────────────────────────────────────────────────────────────────────

-- ============================================================================
--  Mizan · 0008 · Book covers: choose an image or a typeset (text) cover, and its colour.
--  cover_url is kept when switching to text, so switching back restores the image.
-- ============================================================================

alter table public.books add column if not exists cover_mode text not null default 'text';
alter table public.books add column if not exists cover_color text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'books_cover_mode_check') then
    alter table public.books add constraint books_cover_mode_check check (cover_mode in ('image', 'text'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'books_cover_color_check') then
    alter table public.books add constraint books_cover_color_check check (cover_color is null or cover_color ~ '^#[0-9a-f]{6}$');
  end if;
end;
$$;

-- Existing books that already have an image keep showing it.
update public.books set cover_mode = 'image' where cover_url is not null and cover_mode = 'text';

-- ────────────────────────────────────────────────────────────────────────────
-- 20261107000009_chat_persona.sql
-- ────────────────────────────────────────────────────────────────────────────

-- ============================================================================
--  Mizan · 0009 · Chat persona: each conversation is with the study tutor or the general assistant.
--  Fixed per thread, so the server's system prompt and tools never change mid-conversation.
-- ============================================================================

alter table public.chat_threads add column if not exists persona text not null default 'tutor';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'chat_threads_persona_check') then
    alter table public.chat_threads add constraint chat_threads_persona_check check (persona in ('tutor', 'assistant'));
  end if;
end;
$$;
